def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.85))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    serious_bids = []
    needy_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            needy_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > 0:
                    serious_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(serious_bids) / len(serious_bids) if serious_bids else 0.0

    units = int(supply / WATER_REQ)
    scarcity = units <= 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days == 1:
        urgency += 1
    if day >= 8:
        urgency += 1

    if scarcity:
        urgency += 2

    pressure = 0
    if highest_prev >= 110:
        pressure = 3
    elif highest_prev >= 90:
        pressure = 2
    elif highest_prev >= 60:
        pressure = 1

    if needy_count >= 1:
        pressure += 1
    if rich_count >= 2:
        pressure += 1

    target = 0.0

    if urgency >= 5:
        if highest_prev > 0:
            target = highest_prev + 4.0
        else:
            target = DAILY_SALARY * 0.95
    elif urgency >= 3:
        if scarcity:
            if highest_prev > 0:
                target = max(DAILY_SALARY * 0.9, highest_prev + 2.0)
            else:
                target = DAILY_SALARY * 0.82
        else:
            if avg_prev > 0:
                target = max(DAILY_SALARY * 0.68, avg_prev + 1.5)
            else:
                target = DAILY_SALARY * 0.62
    else:
        if scarcity:
            if pressure >= 3:
                target = DAILY_SALARY * 0.28
            elif pressure == 2:
                target = DAILY_SALARY * 0.42
            else:
                target = DAILY_SALARY * 0.55
        else:
            if pressure >= 3:
                target = DAILY_SALARY * 0.22
            elif pressure == 2:
                target = DAILY_SALARY * 0.34
            else:
                target = DAILY_SALARY * 0.46

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left >= 3 and urgency < 5:
        reserve_floor = DAILY_SALARY * 1.2
    if budget <= reserve_floor:
        target = min(target, DAILY_SALARY * 0.45 if urgency < 4 else DAILY_SALARY * 0.8)

    if hp >= 8 and no_water_days == 0 and scarcity and pressure >= 2:
        target = min(target, DAILY_SALARY * 0.25)

    bid = min(float(budget), float(target))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}

    # Determine pressure from yesterday's opponent bids
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid on yesterday's highest bid from alive opponents
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        # If low on HP or dehydrated, bid aggressively to ensure water
        if my_hp <= 2 or no_water_days >= 1:
            target_bid = min(my_budget, max(DAILY_SALARY * 0.85, max_prev_bid + 2.0))
        else:
            # Outbid yesterday's highest by a small margin, but not too much
            target_bid = min(my_budget, max(DAILY_SALARY * 0.4, max_prev_bid + 1.5))
    else:
        # No yesterday data from alive opponents, use a moderate bid
        if my_hp <= 2 or no_water_days >= 1:
            target_bid = min(my_budget, DAILY_SALARY * 0.9)
        else:
            target_bid = min(my_budget, DAILY_SALARY * 0.6)

    # Ensure bid is at least 0 and integer
    bid = int(max(0, min(my_budget, target_bid)))
    return bid
